class ModelNew(nn.Module):
    def __init__(
        self,
        num_features,
        eps=1e-5,
        momentum=0.1,
        affine=True,
        track_running_stats=True,
    ):
        super().__init__()
        self.batch_norm = nn.BatchNorm3d(
            num_features,
            eps=eps,
            momentum=momentum,
            affine=affine,
            track_running_stats=track_running_stats,
        )

    def forward(self, x):
        bn = self.batch_norm
        reduction_dims = (0, 2, 3, 4)

        use_batch_stats = self.training or (
            bn.running_mean is None or bn.running_var is None
        )

        if use_batch_stats:
            mean = torch.mean(x, dim=reduction_dims)
            var = torch.var(x, dim=reduction_dims, unbiased=False)

            if self.training and bn.track_running_stats:
                if bn.num_batches_tracked is not None:
                    with torch.no_grad():
                        bn.num_batches_tracked.add_(1)

                    if bn.momentum is None:
                        exponential_average_factor = (
                            1.0 / float(bn.num_batches_tracked.item())
                        )
                    else:
                        exponential_average_factor = bn.momentum
                else:
                    exponential_average_factor = (
                        0.0 if bn.momentum is None else bn.momentum
                    )

                elements_per_channel = x.numel() // x.shape[1]

                with torch.no_grad():
                    detached_mean = mean.detach()
                    detached_var = var.detach()

                    if elements_per_channel > 1:
                        detached_var = detached_var * (
                            float(elements_per_channel)
                            / float(elements_per_channel - 1)
                        )

                    bn.running_mean.mul_(
                        1.0 - exponential_average_factor
                    ).add_(
                        detached_mean,
                        alpha=exponential_average_factor,
                    )
                    bn.running_var.mul_(
                        1.0 - exponential_average_factor
                    ).add_(
                        detached_var,
                        alpha=exponential_average_factor,
                    )
        else:
            mean = bn.running_mean
            var = bn.running_var

        adjusted_var = _variance_eps(var, bn.eps)
        invstd = torch.rsqrt(adjusted_var)

        broadcast_shape = (1, x.shape[1], 1, 1, 1)
        out = x.clone()
        out.sub_(mean.reshape(broadcast_shape))
        out.mul_(invstd.reshape(broadcast_shape))

        if bn.affine:
            out.mul_(bn.weight.reshape(broadcast_shape))
            out.add_(bn.bias.reshape(broadcast_shape))

        return out

