import torch
import torch.nn as nn
import triton
import triton.language as tl


# POW_MODE encoding (selected on the host from the exponent value):
#   0: exponent == 0       -> y = 1
#   1: exponent == 1       -> y = t
#   2: exponent == 2       -> y = t*t
#   3: exponent == 3       -> y = t*t*t
#   4: exponent == 0.5     -> y = sqrt(t)
#   5: other even integer  -> y = exp(e * log(|t|))
#   6: other odd integer   -> y = sign(t) * exp(e * log(|t|))
#   7: non-integer         -> y = exp(e * log(t))  (NaN for t < 0, like torch.pow)
@triton.jit
def _div_pow_kernel(
    x_ptr,
    d_ptr,
    out_ptr,
    n_elements,
    exponent,
    DIV_SCALAR: tl.constexpr,
    POW_MODE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements

    x = tl.load(x_ptr + offs, mask=mask)
    if DIV_SCALAR:
        d = tl.load(d_ptr)
    else:
        d = tl.load(d_ptr + offs, mask=mask)

    t = (x / d).to(tl.float32)

    if POW_MODE == 0:
        y = tl.where(t >= 0, 1.0, 1.0)  # exactly 1.0 everywhere, incl. NaN
    elif POW_MODE == 1:
        y = t
    elif POW_MODE == 2:
        y = t * t
    elif POW_MODE == 3:
        y = t * t * t
    elif POW_MODE == 4:
        y = tl.sqrt(t)
    elif POW_MODE == 5:
        at = tl.where(t >= 0, t, -t)
        y = tl.exp(exponent * tl.log(at))
    elif POW_MODE == 6:
        at = tl.where(t >= 0, t, -t)
        mag = tl.exp(exponent * tl.log(at))
        y = tl.where(t < 0, -mag, mag)
    else:
        y = tl.exp(exponent * tl.log(t))

    tl.store(out_ptr + offs, y.to(out_ptr.dtype.element_ty), mask=mask)


def _pow_mode(exponent):
    e = float(exponent)
    if e == 0.0:
        return 0
    if e == 1.0:
        return 1
    if e == 2.0:
        return 2
    if e == 3.0:
        return 3
    if e == 0.5:
        return 4
    if e == e and abs(e) < 9.0e15:
        ie = int(e)
        if e == ie:
            return 5 if (ie % 2 == 0) else 6
    return 7


def _div_pow(x, divisor, exponent):
    x = x.contiguous()
    if not torch.is_tensor(divisor):
        divisor = torch.as_tensor(divisor)
    divisor = divisor.to(device=x.device, dtype=x.dtype)

    out = torch.empty_like(x)
    n_elements = x.numel()
    if n_elements == 0:
        return out

    # Avoid materializing a full-size expanded divisor when possible.
    if divisor.numel() == 1:
        d_arg = divisor.contiguous()
        div_scalar = True
    elif divisor.numel() == n_elements:
        d_arg = divisor.contiguous()
        div_scalar = False
    else:
        d_arg = divisor.expand_as(x).contiguous()
        div_scalar = False

    BLOCK = 1024
    grid = (triton.cdiv(n_elements, BLOCK),)
    _div_pow_kernel[grid](
        x,
        d_arg,
        out,
        n_elements,
        float(exponent),
        DIV_SCALAR=div_scalar,
        POW_MODE=_pow_mode(exponent),
        BLOCK=BLOCK,
        num_warps=4,
    )
    return out


class ModelNew(nn.Module):
    def __init__(self, input_divisor, exponent):
        super().__init__()
        self.input_divisor = input_divisor
        self.exponent = exponent

    def forward(self, x):
        if isinstance(self.exponent, (int, float)):
            return _div_pow(x, self.input_divisor, self.exponent)
        # Conservative fallback for exotic exponent types: original semantics.
        return torch.pow(x / self.input_divisor, self.exponent)

import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def _pow_fused(
    v,
    EXP: tl.constexpr,
    EXP_IS_INT: tl.constexpr,
    EXP_IS_ODD: tl.constexpr,
):
    if EXP == 0.0:
        y = v * 0.0 + 1.0
    elif EXP == 1.0:
        y = v
    elif EXP == 2.0:
        y = v * v
    elif EXP == -1.0:
        y = 1.0 / v
    elif EXP == 0.5:
        y = tl.sqrt(v)
    elif EXP_IS_INT:
        # integer-valued exponent: |v|^e with sign restored for odd e,
        # matching torch.pow for negative bases.
        a = tl.where(v >= 0.0, v, -v)
        y = tl.exp(EXP * tl.log(a))
        if EXP_IS_ODD:
            y = tl.where(v < 0.0, -y, y)
    else:
        # non-integer exponent: NaN for negative bases, same as torch.pow
        y = tl.exp(EXP * tl.log(v))
    return y


@triton.jit
def _div_pow_scalar_kernel(
    x_ptr,
    d_ptr,
    out_ptr,
    n_elements,
    EXP: tl.constexpr,
    EXP_IS_INT: tl.constexpr,
    EXP_IS_ODD: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements

    x = tl.load(x_ptr + offs, mask=mask)
    d = tl.load(d_ptr)
    v = x / d
    y = _pow_fused(v, EXP, EXP_IS_INT, EXP_IS_ODD)

    tl.store(out_ptr + offs, y, mask=mask)


