    tl.store(out_ptr + offs, y, mask=mask)


def _launch_div_pow(x, d, out, exponent):
    n = x.numel()
    e = float(exponent)
    e_int = e.is_integer()
    e_odd = (int(e) % 2 != 0) if e_int else False

    BLOCK = 1024
    grid = (triton.cdiv(n, BLOCK),)

    if d.numel() == 1:
        _div_pow_scalar_kernel[grid](
            x, d, out, n,
            EXP=e, EXP_IS_INT=e_int, EXP_IS_ODD=e_odd,
            BLOCK=BLOCK,
        )
    else:
        _div_pow_ew_kernel[grid](
            x, d, out, n,
            EXP=e, EXP_IS_INT=e_int, EXP_IS_ODD=e_odd,
            BLOCK=BLOCK,
        )


def _div_pow(x, divisor, exponent):
    x = x.contiguous()
    d = divisor.to(device=x.device, dtype=x.dtype)

    # Rare case: a multi-element tensor exponent cannot be baked in as a
    # constexpr; keep exact semantics with a fused divide (EXP=1) + torch.pow.
    if torch.is_tensor(exponent) and exponent.numel() > 1:
        if d.numel() != 1:
            d = d.expand_as(x).contiguous()
        out = torch.empty_like(x)
        if x.numel() == 0:
            return torch.pow(out, exponent)
        _launch_div_pow(x, d, out, 1.0)
        return torch.pow(out, exponent)

    if d.numel() != 1:
        if d.shape != x.shape:
            d = d.expand_as(x).contiguous()
        else:
            d = d.contiguous()

    out = torch.empty_like(x)
    if x.numel() == 0:
        return out
    _launch_div_pow(x, d, out, exponent)
    return out


