@triton.jit
def _relu_kernel(x_ptr, out_ptr, n_elements, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    x = tl.load(x_ptr + offs, mask=mask)
    y = tl.maximum(x, 0.0)
    tl.store(out_ptr + offs, y, mask=mask)


def _relu_triton(x):
    x = x.contiguous()
    out = torch.empty_like(x)
    n_elements = x.numel()
    BLOCK = 1024
    grid = (triton.cdiv(n_elements, BLOCK),)
    _relu_kernel[grid](x, out, n_elements, BLOCK=BLOCK)
    return out


def _parse_permutation(equation, ndim):
    """Return perm such that einsum(equation, x) == x.permute(perm) for a
    single-operand pure-relabeling equation; otherwise return None."""
    try:
        eq = equation.replace(' ', '')
        if ',' in eq or '.' in eq:  # multi-operand or ellipsis
            return None
        if '->' in eq:
            lhs, rhs = eq.split('->')
        else:
            lhs, rhs = eq, None
        if len(lhs) != ndim or len(set(lhs)) != ndim:
            return None  # wrong rank or repeated label (trace/diag)
        if rhs is None:
            rhs = ''.join(sorted(lhs))
        if len(rhs) != ndim or set(rhs) != set(lhs):
            return None  # reduction or mismatched labels
        return [lhs.index(c) for c in rhs]
    except Exception:
        return None


class ModelNew(nn.Module):
    def __init__(self, einsum_equation, in_channels, out_channels, kernel_size):
        super().__init__()
        self.einsum_equation = einsum_equation
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self._perm_cache = {}

    def forward(self, x):
        ndim = x.dim()
        if ndim not in self._perm_cache:
            self._perm_cache[ndim] = _parse_permutation(self.einsum_equation, ndim)
        perm = self._perm_cache[ndim]
        if perm is not None:
            # einsum(equation, x) is a permuted view and relu is elementwise,
            # so relu(einsum(x)) == relu(x).permute(perm). Running relu on the
            # contiguous input avoids materializing the permuted intermediate.
            return _relu_triton(x).permute(*perm)
        # General fallback: original semantics.
        x = torch.einsum(self.einsum_equation, x)
        x = _relu_triton(x)
        return x
